import { useEffect, useState } from "react";
import axios from "axios";
import { QRCodeCanvas } from "qrcode.react";

function Dashboard() {

  const [form, setForm] = useState({
    patientName: "",
    doctor: "",
    department: "",
    date: ""
  });

  const [queues, setQueues] = useState([]);
  const [notification, setNotification] = useState("");

  // FETCH ALL QUEUES
  const fetchQueues = async () => {

    try {

      const res = await axios.get(
        "http://localhost:5000/api/queue/all"
      );

      setQueues(res.data);

    } catch (err) {

      console.log(err);

    }
  };

  useEffect(() => {
    fetchQueues();
  }, []);

  // BOOK OP
  const addQueue = async () => {

    if (
      !form.patientName ||
      !form.doctor ||
      !form.department ||
      !form.date
    ) {
      alert("Please Fill All Fields");
      return;
    }

    try {

      const res = await axios.post(
        "http://localhost:5000/api/queue/add",
        form
      );

      setNotification(
        `✅ Token ${res.data.tokenNumber} Booked Successfully`
      );

      setForm({
        patientName: "",
        doctor: "",
        department: "",
        date: ""
      });

      fetchQueues();

    } catch (err) {

      console.log(err);

      alert("Book OP Failed");

    }
  };

  // JOIN QUEUE
  const joinQueue = (token) => {

    setNotification(
      `🟢 Patient Joined Queue Successfully | Token ${token}`
    );
  };

  // COMPLETE PATIENT
  const updateStatus = async (id, status) => {

    try {

      await axios.put(
        `http://localhost:5000/api/queue/update/${id}`,
        {
          status
        }
      );

      setNotification(
        "✅ Patient Consultation Completed"
      );

      fetchQueues();

    } catch (err) {

      console.log(err);

    }
  };

  return (

    <div
      style={{
        padding: "40px",
        background: "#f1f5f9",
        minHeight: "100vh"
      }}
    >

      <h1
        style={{
          textAlign: "center",
          color: "#1d4ed8",
          marginBottom: "30px"
        }}
      >
        PulseLine Smart Queue System
      </h1>

      {/* NOTIFICATION */}
      {notification && (

        <div
          style={{
            background: "#22c55e",
            color: "white",
            padding: "15px",
            borderRadius: "10px",
            marginBottom: "25px",
            fontWeight: "bold",
            textAlign: "center"
          }}
        >
          {notification}
        </div>
      )}

      {/* BOOK OP FORM */}
      <div
        style={{
          background: "white",
          padding: "25px",
          borderRadius: "15px",
          marginBottom: "30px",
          boxShadow: "0 0 10px rgba(0,0,0,0.1)"
        }}
      >

        <h2>Book OP Appointment</h2>

        <input
          type="text"
          placeholder="Patient Name"
          value={form.patientName}
          onChange={(e) =>
            setForm({
              ...form,
              patientName: e.target.value
            })
          }
          style={inputStyle}
        />

        <input
          type="text"
          placeholder="Doctor Name"
          value={form.doctor}
          onChange={(e) =>
            setForm({
              ...form,
              doctor: e.target.value
            })
          }
          style={inputStyle}
        />

        <input
          type="text"
          placeholder="Department"
          value={form.department}
          onChange={(e) =>
            setForm({
              ...form,
              department: e.target.value
            })
          }
          style={inputStyle}
        />

        <input
          type="date"
          value={form.date}
          onChange={(e) =>
            setForm({
              ...form,
              date: e.target.value
            })
          }
          style={inputStyle}
        />

        <button
          onClick={addQueue}
          style={buttonStyle}
        >
          Book OP
        </button>

      </div>

      {/* QUEUE LIST */}
      <h2 style={{ marginBottom: "20px" }}>
        Patient Queue List
      </h2>

      {queues.map((q) => (

        <div
          key={q._id}
          style={{
            background: "white",
            padding: "20px",
            borderRadius: "15px",
            marginBottom: "20px",
            boxShadow: "0 0 10px rgba(0,0,0,0.1)"
          }}
        >

          <h3 style={{ color: "#2563eb" }}>
            Token Number: {q.tokenNumber}
          </h3>

          <p>
            <strong>Patient:</strong> {q.patientName}
          </p>

          <p>
            <strong>Doctor:</strong> {q.doctor}
          </p>

          <p>
            <strong>Department:</strong> {q.department}
          </p>

          <p>
            <strong>Date:</strong> {q.date}
          </p>

          <p>
            <strong>Status:</strong> {q.status}
          </p>

          {/* QR CODE */}
          <QRCodeCanvas
            value={JSON.stringify({
              token: q.tokenNumber,
              patient: q.patientName,
              doctor: q.doctor
            })}
            size={130}
          />

          <br />
          <br />

          {/* JOIN QUEUE */}
          <button
            onClick={() =>
              joinQueue(q.tokenNumber)
            }
            style={{
              background: "#16a34a",
              color: "white",
              border: "none",
              padding: "10px 15px",
              borderRadius: "8px",
              marginRight: "10px",
              cursor: "pointer"
            }}
          >
            Join Queue
          </button>

          {/* COMPLETE */}
          <button
            onClick={() =>
              updateStatus(q._id, "Completed")
            }
            style={{
              background: "#dc2626",
              color: "white",
              border: "none",
              padding: "10px 15px",
              borderRadius: "8px",
              cursor: "pointer"
            }}
          >
            Complete
          </button>

        </div>
      ))}

    </div>
  );
}

// INPUT STYLE
const inputStyle = {
  width: "100%",
  padding: "12px",
  marginBottom: "15px",
  borderRadius: "8px",
  border: "1px solid #ccc",
  fontSize: "16px"
};

// BUTTON STYLE
const buttonStyle = {
  background: "#2563eb",
  color: "white",
  padding: "12px 20px",
  border: "none",
  borderRadius: "8px",
  cursor: "pointer",
  fontSize: "16px"
};

export default Dashboard;
